"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import SearchSelect from "./ui/SearchSelect";
import { useSWRConfig } from "swr";
import {
    Cloud,
    HardDrive,
    MonitorCheck,
    Users,
    CheckCircle2,
    ArrowRight,
    ArrowLeft,
    DollarSign,
    Target,
    Calendar,
    Clock,
    Flame,
    Sparkles,
    MapPin,
    User,
    FileUp,
    Briefcase,
    Zap
} from "lucide-react";
import { cn } from "@/lib/utils";
import axios from "axios";
import { useSimulation } from "@/components/SimulationProvider";
import { calculateCommission } from "@/lib/rulesEngine";

const orderSchema = z.object({
    // Step 1
    productId: z.number().min(1, "Selecione um produto"),
    customPrice: z.number().min(1, "Preço inválido"),
    doc: z.string().min(11, "Documento inválido"),
    name: z.string().min(3, "Razão Social/Nome Completo obrigatório"),
    fantasyName: z.string().optional(),
    legalRepName: z.string().optional(),
    legalRepCpf: z.string().optional(),
    email: z.string().email("E-mail inválido"),
    phone: z.string().min(10, "Telefone inválido"),
    cep: z.string().min(8, "CEP inválido"),
    street: z.string().min(3, "Logradouro obrigatório"),
    number: z.string().min(1, "Número obrigatório"),
    neighborhood: z.string().min(2, "Bairro obrigatório"),
    city: z.string().min(2, "Cidade obrigatória"),
    state: z.string().length(2, "UF deve ter 2 caracteres"),
    complement: z.string().optional(),
    // Step 2
    mediaType: z.enum(["Nuvem", "Token", "Cartão"]),
    validity: z.string(),
    videoConference: z.boolean(),
    appointmentDate: z.string().optional(),
    appointmentTime: z.string().optional(),
    // Step 3
    billingType: z.enum(["Mesmo", "Diferente"]),
    billingDoc: z.string().optional(),
    billingName: z.string().optional(),
    coupon: z.string().optional(),
});

type OrderFormData = z.infer<typeof orderSchema>;

interface OrderJourneyModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    products: any[];
}

export default function OrderJourneyModal({ isOpen, onClose, onSubmit, products }: OrderJourneyModalProps) {
    const { currentUser, updateUser } = useSimulation();
    const { mutate } = useSWRConfig();
    const [step, setStep] = useState(1);
    const [isConsulting, setIsConsulting] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState<"PF" | "PJ" | null>(null);

    const {
        register,
        handleSubmit,
        watch,
        setValue,
        reset,
        formState: { errors, isValid }
    } = useForm<OrderFormData>({
        resolver: zodResolver(orderSchema),
        defaultValues: {
            productId: 0,
            customPrice: 0,
            doc: "",
            name: "",
            fantasyName: "",
            legalRepName: "",
            legalRepCpf: "",
            email: "",
            phone: "",
            cep: "",
            street: "",
            number: "",
            neighborhood: "",
            city: "",
            state: "",
            complement: "",
            mediaType: "Nuvem",
            validity: "12 Meses",
            videoConference: true,
            billingType: "Mesmo",
            coupon: "",
        }
    });

    const selectedProductId = watch("productId");
    const selectedProduct = products.find(p => p.id === selectedProductId);

    // Sync custom price when product changes
    useEffect(() => {
        if (selectedProduct) {
            setValue("customPrice", selectedProduct.price);
        }
    }, [selectedProductId, selectedProduct, setValue]);

    const customPrice = watch("customPrice");
    const cepValue = watch("cep");
    const docValue = watch("doc");
    const videoConference = watch("videoConference");
    const billingType = watch("billingType");
    const isPJ = selectedCategory === "PJ";

    // Filter products based on selected category
    const filteredProducts = products.filter(p => {
        if (!selectedCategory) return false;
        if (selectedCategory === "PF") return p.category === "CPF";
        if (selectedCategory === "PJ") return p.category === "CNPJ";
        return true;
    });

    // Dynamic Commission Logic
    const commissionData = selectedProduct ? calculateCommission(
        customPrice || selectedProduct.price,
        currentUser.level,
        isPJ,
        currentUser.equippedBadge
    ) : null;

    // Auto-fill logic for CPF/CNPJ
    useEffect(() => {
        const fetchCustomer = async () => {
            const cleanDoc = docValue?.replace(/[^0-9]/g, '');
            if (cleanDoc && (cleanDoc.length === 11 || cleanDoc.length === 14)) {
                setIsConsulting(true);
                try {
                    const { data } = await axios.get(`/api/consulta/clientes?doc=${cleanDoc}`);
                    setValue("name", data.name);
                    setValue("email", data.email);
                    setValue("phone", data.phone);
                } catch (e) {
                    // Not found or error
                } finally {
                    setIsConsulting(false);
                }
            }
        };

        const timer = setTimeout(fetchCustomer, 1000);
        return () => clearTimeout(timer);
    }, [docValue, setValue]);

    // Auto-fill logic for CEP
    useEffect(() => {
        const fetchAddress = async () => {
            const cleanCep = cepValue?.replace(/[^0-9]/g, '');
            if (cleanCep && cleanCep.length === 8) {
                try {
                    const { data } = await axios.get(`https://viacep.com.br/ws/${cleanCep}/json/`);
                    if (!data.erro) {
                        setValue("street", data.logradouro);
                        setValue("neighborhood", data.bairro);
                        setValue("city", data.localidade);
                        setValue("state", data.uf);
                    }
                } catch (e) {
                    // Silent error
                }
            }
        };

        const timer = setTimeout(fetchAddress, 500);
        return () => clearTimeout(timer);
    }, [cepValue, setValue]);

    const handleNext = () => setStep(s => Math.min(s + 1, 4));
    const handleBack = () => setStep(s => Math.max(s - 1, 1));

    const renderStep1 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6">1. Inicie o Pedido</h3>

                {/* Category Selection */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
                    <button
                        type="button"
                        onClick={() => {
                            setSelectedCategory("PF");
                            setValue("productId", 0);
                        }}
                        className={cn(
                            "p-6 rounded-[2.5rem] border-2 text-left transition-all relative group overflow-hidden",
                            selectedCategory === "PF"
                                ? "border-primary bg-primary/5 shadow-xl shadow-primary/10"
                                : "border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 bg-white dark:bg-slate-900"
                        )}
                    >
                        <div className="flex items-center gap-4 relative z-10">
                            <div className={cn(
                                "size-12 rounded-2xl flex items-center justify-center transition-colors",
                                selectedCategory === "PF" ? "bg-primary text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                            )}>
                                <User size={24} />
                            </div>
                            <div>
                                <p className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">Pessoa Física</p>
                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Para você ou cliente CPF</p>
                            </div>
                            {selectedCategory === "PF" && <CheckCircle2 className="text-primary ml-auto" size={20} />}
                        </div>
                    </button>

                    <button
                        type="button"
                        onClick={() => {
                            setSelectedCategory("PJ");
                            setValue("productId", 0);
                        }}
                        className={cn(
                            "p-6 rounded-[2.5rem] border-2 text-left transition-all relative group overflow-hidden",
                            selectedCategory === "PJ"
                                ? "border-primary bg-primary/5 shadow-xl shadow-primary/10"
                                : "border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 bg-white dark:bg-slate-900"
                        )}
                    >
                        <div className="flex items-center gap-4 relative z-10">
                            <div className={cn(
                                "size-12 rounded-2xl flex items-center justify-center transition-colors",
                                selectedCategory === "PJ" ? "bg-primary text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                            )}>
                                <Briefcase size={24} />
                            </div>
                            <div>
                                <p className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">Pessoa Jurídica</p>
                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Para empresas e CNPJs</p>
                            </div>
                            {selectedCategory === "PJ" && <CheckCircle2 className="text-primary ml-auto" size={20} />}
                        </div>
                    </button>
                </div>

                {selectedCategory && (
                    <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Produtos Disponíveis</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {filteredProducts.map((product) => (
                                <button
                                    key={product.id}
                                    type="button"
                                    onClick={() => setValue("productId", product.id)}
                                    className={cn(
                                        "p-5 rounded-[2rem] border-2 text-left transition-all relative group",
                                        selectedProductId === product.id
                                            ? "border-primary bg-primary/5 shadow-xl shadow-primary/10"
                                            : "border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 bg-white dark:bg-slate-900"
                                    )}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className={cn(
                                            "size-12 rounded-2xl flex items-center justify-center transition-colors",
                                            selectedProductId === product.id ? "bg-primary text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                                        )}>
                                            {product.type === "A1" ? <Cloud size={24} /> : <HardDrive size={24} />}
                                        </div>
                                        <div className="flex-1">
                                            <p className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">{product.name}</p>
                                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{product.category} • {product.type}</p>
                                        </div>
                                        {selectedProductId === product.id && <CheckCircle2 className="text-primary" size={20} />}
                                    </div>
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {selectedProduct && (
                <div className="bg-primary/5 rounded-[2rem] p-6 border border-primary/10 animate-in zoom-in-95">
                    <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                        <div>
                            <h4 className="text-xs font-black uppercase tracking-tight text-primary mb-1">Poder de Negociação</h4>
                            <p className="text-[10px] text-slate-500 font-bold">Ajuste o valor final para o cliente</p>
                        </div>
                        <div className="flex items-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-1 w-full md:w-auto">
                            <span className="px-3 text-xs font-black text-slate-400">R$</span>
                            <input
                                type="number"
                                {...register("customPrice", { valueAsNumber: true })}
                                className="flex-1 md:w-24 bg-transparent border-0 focus:ring-0 text-sm font-black text-slate-900 dark:text-white p-2"
                            />
                        </div>
                    </div>
                </div>
            )}
        </div>
    );

    const renderStep2 = () => (
        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4">2. Dados do Titular</h3>
                <div className="space-y-4">
                    <Input label="CPF ou CNPJ" {...register("doc")} error={errors.doc?.message} placeholder="Busca automática..." helpText={isConsulting ? "Buscando..." : ""} />
                    <Input label="Razão Social / Nome Completo" {...register("name")} error={errors.name?.message} />

                    {isPJ && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in">
                            <Input label="Representante Legal" {...register("legalRepName")} placeholder="Nome do representante" />
                            <Input label="CPF Representante" {...register("legalRepCpf")} placeholder="000.000.000-00" />
                        </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input label="WhatsApp" {...register("phone")} error={errors.phone?.message} />
                        <Input label="E-mail" {...register("email")} error={errors.email?.message} />
                    </div>
                </div>
            </div>

            <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4">Endereço de Correspondência</h3>
                <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Input label="CEP" {...register("cep")} error={errors.cep?.message} placeholder="00000-000" />
                        <div className="md:col-span-2">
                            <Input label="Logradouro" {...register("street")} error={errors.street?.message} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        <Input label="Número" {...register("number")} error={errors.number?.message} />
                        <Input label="Bairro" {...register("neighborhood")} error={errors.neighborhood?.message} />
                        <Input label="Cidade" {...register("city")} error={errors.city?.message} />
                        <Input label="UF" {...register("state")} error={errors.state?.message} maxLength={2} />
                    </div>
                </div>
            </div>

            {/* Document Attachment Simulation */}
            <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
                <div className="p-6 bg-slate-50 dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[2rem] flex flex-col items-center gap-4 text-center">
                    <div className="size-12 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400">
                        <FileUp size={24} />
                    </div>
                    <div>
                        <p className="text-sm font-black">Anexar Documento</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">PDF ou Imagem (Máx 20MB)</p>
                    </div>
                    <button type="button" className="px-6 py-2 bg-primary text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-primary/20">
                        Selecionar Arquivo
                    </button>
                </div>
            </div>
        </div>
    );

    const renderStep3 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <div className="bg-slate-50 dark:bg-slate-800/50 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                    <MonitorCheck size={18} className="text-primary" /> Configurações de Emissão
                </h3>

                <div className="space-y-8">
                    <SegmentedControl
                        label="Tipo de Mídia"
                        value={watch("mediaType")}
                        onChange={(v) => setValue("mediaType", v as any)}
                        options={[
                            { label: "Nuvem (A1)", value: "Nuvem" },
                            { label: "Token (A3)", value: "Token" },
                            { label: "Cartão (A3)", value: "Cartão" },
                        ]}
                    />

                    <SegmentedControl
                        label="Modalidade de Atendimento"
                        value={videoConference ? "video" : "presencial"}
                        onChange={(v) => setValue("videoConference", v === "video")}
                        options={[
                            { label: "Videoconferência", value: "video" },
                            { label: "Presencial (Hub)", value: "presencial" },
                        ]}
                    />

                    {videoConference && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in zoom-in-95">
                            <Input label="Data" type="date" {...register("appointmentDate")} />
                            <Input label="Horário" type="time" {...register("appointmentTime")} />
                        </div>
                    )}
                </div>
            </div>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                    <DollarSign size={18} className="text-primary" /> Dados para Fatura
                </h3>

                <div className="space-y-6">
                    <SegmentedControl
                        label="Faturar para:"
                        value={billingType}
                        onChange={(v) => setValue("billingType", v as any)}
                        options={[
                            { label: "Mesmo Titular", value: "Mesmo" },
                            { label: "Dados Diferentes", value: "Diferente" },
                        ]}
                    />

                    {billingType === "Diferente" && (
                        <div className="space-y-4 animate-in slide-in-from-top-2">
                            <Input label="CPF/CNPJ Faturamento" {...register("billingDoc")} />
                            <Input label="Nome/Razão Social" {...register("billingName")} />
                        </div>
                    )}
                </div>
            </div>
        </div>
    );

    const renderStep4 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <div className="bg-slate-950 border-2 border-primary/30 rounded-[2.5rem] p-10 relative overflow-hidden shadow-2xl shadow-primary/20">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-primary/20 via-transparent to-transparent opacity-50 animate-pulse" />

                <div className="relative z-10 flex flex-col items-center text-center">
                    <div className="size-20 rounded-[2rem] bg-gradient-to-br from-emerald-400 to-emerald-600 text-white flex items-center justify-center mb-8 shadow-2xl shadow-emerald-500/40 animate-bounce">
                        <DollarSign size={40} />
                    </div>

                    <h3 className="text-3xl font-black text-white mb-3 tracking-tight">Pronto para Lucrar?</h3>
                    <p className="text-sm text-slate-400 max-w-xs mx-auto mb-10 font-medium">Sua comissão está reservada! Finalize o pedido e veja seu XP explodir.</p>

                    <div className="w-full bg-white/5 backdrop-blur-md rounded-3xl border border-white/10 overflow-hidden overflow-x-auto">
                        <table className="w-full text-left text-[10px] uppercase font-bold text-slate-400 min-w-[300px]">
                            <thead className="bg-white/5 border-b border-white/5">
                                <tr>
                                    <th className="px-6 py-4">Produto</th>
                                    <th className="px-6 py-4 text-right">Preço</th>
                                    <th className="px-6 py-4 text-right text-primary">Ganho</th>
                                </tr>
                            </thead>
                            <tbody className="text-white">
                                <tr className="border-b border-white/5">
                                    <td className="px-6 py-5 font-black">{selectedProduct?.name}</td>
                                    <td className="px-6 py-5 text-right font-black">{customPrice?.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</td>
                                    <td className="px-6 py-5 text-right font-black text-emerald-400 text-sm">
                                        {commissionData?.commission?.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                        <div className="p-6 bg-emerald-500/10 flex flex-col sm:flex-row justify-between items-center gap-4">
                            <div className="flex items-center gap-2 text-indigo-400">
                                <Sparkles size={16} />
                                <span className="text-lg font-black">{selectedProduct && Math.floor(customPrice)} XP</span>
                            </div>
                            <div className="flex gap-2">
                                <span className="px-3 py-1 bg-white/10 rounded-full text-[8px] text-white whitespace-nowrap">TAXA INCLUÍDA</span>
                                <span className="px-3 py-1 bg-white/10 rounded-full text-[8px] text-white whitespace-nowrap">MARGEM GARANTIDA</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="size-12 rounded-2xl bg-indigo-500/10 text-indigo-500 flex items-center justify-center">
                        <Flame size={24} />
                    </div>
                    <div>
                        <p className="text-xs font-black text-slate-900 dark:text-white uppercase tracking-tight">O dobro de pontos!</p>
                        <p className="text-[11px] text-slate-500 font-medium">Sua sequência de 5 dias está ativa.</p>
                    </div>
                </div>
                <div className="text-[10px] font-black text-indigo-500 bg-indigo-500/5 px-3 py-1.5 rounded-full uppercase tracking-widest">
                    Combo Ativo
                </div>
            </div>
        </div>
    );

    const onSubmitAction = async (data: OrderFormData) => {
        setIsConsulting(true);
        try {
            const response = await axios.post('/api/integracao/vendas', data);

            // Recompensa o usuário localmente
            if (commissionData) {
                updateUser({
                    xp: currentUser.xp + Math.floor(customPrice),
                    wallet: currentUser.wallet + commissionData.commission
                });
            }

            mutate('/api/certificates');
            alert(`Sucesso! Protocolo: ${response.data.protocol}. Link de pagamento gerado.`);
            onClose();
            onSubmit(data);
        } catch (error) {
            alert("Erro ao finalizar pedido.");
        } finally {
            setIsConsulting(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Nova Emissão de Certificado"
            width="4xl"
        >
            <div className="flex flex-col md:flex-row h-auto md:h-[85vh] -m-4 md:-m-8">
                {/* Stepper Sidebar - Hidden on tiny screens, or vertical on mobile */}
                <div className="hidden md:flex w-80 bg-slate-50 dark:bg-slate-950 p-10 border-r border-slate-100 dark:border-slate-800 flex-col">
                    <div className="mb-12">
                        <div className="size-12 rounded-2xl bg-primary flex items-center justify-center text-white shadow-xl shadow-primary/20 mb-6 font-black italic">Δ</div>
                        <h2 className="text-2xl font-black tracking-tighter">Novo Pedido</h2>
                    </div>

                    <div className="space-y-6 flex-1">
                        {[
                            { n: 1, label: "Produto & Valor", icon: Zap },
                            { n: 2, label: "Dados Titular", icon: User },
                            { n: 3, label: "Técnico & Fatura", icon: Briefcase },
                            { n: 4, label: "Revisão Final", icon: CheckCircle2 },
                        ].map((s) => (
                            <div key={s.n} className={cn(
                                "flex items-center gap-4 transition-all duration-300",
                                step >= s.n ? "opacity-100" : "opacity-30"
                            )}>
                                <div className={cn(
                                    "size-10 rounded-xl flex items-center justify-center transition-all shadow-lg",
                                    step === s.n ? "bg-primary text-white scale-110" : step > s.n ? "bg-emerald-500 text-white" : "bg-white dark:bg-slate-800 text-slate-400"
                                )}>
                                    <s.icon size={20} />
                                </div>
                                <div className="flex flex-col">
                                    <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest leading-none mb-1">Passo 0{s.n}</p>
                                    <p className="text-xs font-bold">{s.label}</p>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Reward Preview Card */}
                    <div className="mt-auto bg-slate-900 rounded-[2rem] p-6 text-white relative overflow-hidden group">
                        <div className="relative z-10">
                            <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mb-2">Seu Ganho Estimado</p>
                            <p className="text-3xl font-black tracking-tighter mb-1">
                                {commissionData ? commissionData.commission.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : "R$ 0,00"}
                            </p>
                            <p className="text-[10px] text-slate-500 font-bold uppercase">Meta de Nível: {currentUser.level === 'Bronze' ? 'Prata' : 'Ouro'}</p>
                        </div>
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                            <DollarSign size={60} />
                        </div>
                    </div>
                </div>

                {/* Main Content Area */}
                <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 min-h-[500px]">
                    <div className="flex-1 overflow-y-auto p-6 md:p-12">
                        {/* Mobile Stepper Indicator */}
                        <div className="flex md:hidden items-center justify-between mb-8 pb-4 border-b border-slate-100 dark:border-slate-800">
                            <div className="flex flex-col">
                                <p className="text-[10px] font-black uppercase text-primary tracking-widest leading-none mb-1">Passo 0{step}</p>
                                <p className="text-sm font-black">{step === 1 ? "Produto & Valor" : step === 2 ? "Dados Titular" : step === 3 ? "Técnico & Fatura" : "Revisão Final"}</p>
                            </div>
                            <div className="flex gap-1">
                                {[1, 2, 3, 4].map(i => (
                                    <div key={i} className={cn("h-1 w-6 rounded-full transition-all", step === i ? "bg-primary w-10" : step > i ? "bg-emerald-500" : "bg-slate-200 dark:bg-slate-800")} />
                                ))}
                            </div>
                        </div>

                        {step === 1 && renderStep1()}
                        {step === 2 && renderStep2()}
                        {step === 3 && renderStep3()}
                        {step === 4 && renderStep4()}
                    </div>

                    <div className="p-6 md:p-8 bg-slate-50 dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 flex flex-col md:flex-row gap-4 justify-between items-center">
                        <button
                            type="button"
                            onClick={step === 1 ? onClose : handleBack}
                            className="order-2 md:order-1 w-full md:w-auto px-8 py-4 text-sm font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 dark:hover:text-white transition-colors"
                        >
                            {step === 1 ? "Cancelar" : "Voltar"}
                        </button>

                        {step < 4 ? (
                            <button
                                type="button"
                                onClick={handleNext}
                                disabled={!selectedProductId}
                                className="order-1 md:order-2 w-full md:w-auto bg-slate-900 dark:bg-white dark:text-slate-900 text-white px-10 py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
                            >
                                Próxima Etapa
                            </button>
                        ) : (
                            <button
                                type="button"
                                onClick={handleSubmit(onSubmitAction)}
                                className="order-1 md:order-2 w-full md:w-auto bg-primary text-white px-10 py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all"
                            >
                                Finalizar Emissão
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </Modal>
    );
}
